    if (game.cells[b] === mark && game.cells[c] === mark) {
      return mark;
    }
    return null;
  }

  winnerOf(game: Game): string | null {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];

    for (const line of lines) {
      const winner = this.lineWinner(game, line[0], line[1], line[2]);
      if (winner) {
        return winner;
      }
    }

    return null;
  }

  isDraw(game: Game): boolean {
    return !game.cells.includes(" ");
  }

  render(game: Game): string {
    return `${game.cells[0]}|${game.cells[1]}|${game.cells[2]}\n${game.cells[3]}|${game.cells[4]}|${game.cells[5]}\n${game.cells[6]}|${game.cells[7]}|${game.cells[8]}`;
  }
}
